"""
soot_analysis.py — Soot-style foundation layer.

Builds the Jimple-like IR view over the shared program model and provides the
core whole-program analysis utilities:

- ``Scene``: the whole-program registry (classes, methods, hierarchy).
- ``CFG`` / ``build_cfg``: control-flow graphs over method bodies.
- ``build_cha_call_graph``: class-hierarchy-analysis call-graph construction.
- ``copy_propagate`` / ``eliminate_dead_code``: classic Jimple optimizations.

Runs standalone: ``python3 soot_analysis.py [benchmarks_dir]`` and prints
``KEY: VALUE`` experiment lines per benchmark.
"""

from __future__ import annotations

import os
import sys
from collections import defaultdict, deque

from program_model import (
    ClassDef,
    Method,
    MethodBody,
    MethodSignature,
    Program,
    Statement,
    load_program,
)
from utils import (
    Timer,
    build_class_index,
    build_hierarchy,
    build_method_index,
    get_all_subclasses,
)


# ---------------------------------------------------------------------------
# Scene: whole-program registry
# ---------------------------------------------------------------------------

class Scene:
    """Registry of all classes/methods of a program (Soot's ``Scene``)."""

    def __init__(self, program: Program):
        self.program = program
        self.classes: dict[str, ClassDef] = build_class_index(program)
        self.methods: dict[str, tuple[ClassDef, Method]] = build_method_index(program)
        self.hierarchy: dict[str, list[str]] = build_hierarchy(program)

    def get_class(self, name: str) -> ClassDef | None:
        return self.classes.get(name)

    def get_method(self, full_signature: str) -> tuple[ClassDef, Method] | None:
        return self.methods.get(full_signature)

    def resolve_method(
        self, class_name: str, method_name: str, param_types: list[str]
    ) -> tuple[ClassDef, Method] | None:
        """Resolve a method by walking the superclass chain (name + arity)."""
        visited: set[str] = set()
        current = class_name
        while current and current not in visited:
            visited.add(current)
            cls = self.classes.get(current)
            if cls is None:
                break
            for method in cls.methods:
                sig = method.signature
                if sig.method_name == method_name and (
                    list(sig.param_types) == list(param_types)
                    or len(sig.param_types) == len(param_types)
                ):
                    return (cls, method)
            current = cls.super_class
        return None

    def all_subclasses(self, class_name: str) -> set[str]:
        return get_all_subclasses(self.hierarchy, class_name)

    def entry_methods(self) -> list[tuple[ClassDef, Method]]:
        """Resolve the program's declared entry points to concrete methods."""
        result: list[tuple[ClassDef, Method]] = []
        for sig in self.program.entry_points:
            resolved = self.resolve_method(sig.class_name, sig.method_name, sig.param_types)
            if resolved is not None:
                result.append(resolved)
        # Also honor methods explicitly flagged as entry points.
        known = {m.signature.full_signature() for _, m in result}
        for cls in self.program.classes:
            for method in cls.methods:
                if method.is_entry_point and method.signature.full_signature() not in known:
                    result.append((cls, method))
                    known.add(method.signature.full_signature())
        return result


# ---------------------------------------------------------------------------
# Control-flow graph over the Jimple-like statement list
# ---------------------------------------------------------------------------

class CFG:
    """Statement-level control-flow graph for one method body."""

    def __init__(self, body: MethodBody):
        self.statements: list[Statement] = list(body.statements)
        self.successors: dict[int, list[int]] = defaultdict(list)
        self.predecessors: dict[int, list[int]] = defaultdict(list)
        ids = [s.stmt_id for s in self.statements]
        id_set = set(ids)
        for i, stmt in enumerate(self.statements):
            succs: list[int] = []
            if stmt.kind == "if":
                for target in (stmt.true_target, stmt.false_target):
                    if target is not None and target in id_set:
                        succs.append(target)
            elif stmt.kind == "return":
                succs = []
            else:
                if i + 1 < len(self.statements):
                    succs.append(self.statements[i + 1].stmt_id)
            # Exceptional edges from trap handlers.
            for trap in body.trap_handlers:
                begin, end, handler = (
                    trap.get("begin_id"),
                    trap.get("end_id"),
                    trap.get("handler_id"),
                )
                if (
                    handler is not None
                    and begin is not None
                    and end is not None
                    and begin <= stmt.stmt_id <= end
                    and handler in id_set
                    and handler not in succs
                ):
                    succs.append(handler)
            for target in succs:
                self.successors[stmt.stmt_id].append(target)
                self.predecessors[target].append(stmt.stmt_id)

    def entry_ids(self) -> list[int]:
        return [self.statements[0].stmt_id] if self.statements else []

    def exit_ids(self) -> list[int]:
        return [s.stmt_id for s in self.statements if not self.successors.get(s.stmt_id)]


def build_cfg(body: MethodBody) -> CFG:
    return CFG(body)


# ---------------------------------------------------------------------------
# CHA call graph
# ---------------------------------------------------------------------------

class CallGraph:
    """Class-hierarchy-analysis call graph."""

    def __init__(self):
        self.edges: set[tuple[str, str]] = set()
        self.call_sites: dict[str, list[tuple[int, str]]] = defaultdict(list)
        self.external_callees: set[str] = set()

    def add_edge(self, caller_sig: str, stmt_id: int, callee_sig: str):
        self.edges.add((caller_sig, callee_sig))
        site = (stmt_id, callee_sig)
        if site not in self.call_sites[caller_sig]:
            self.call_sites[caller_sig].append(site)

    def callees_from(self, caller_sig: str) -> set[str]:
        return {dst for src, dst in self.edges if src == caller_sig}

    def callers_of(self, callee_sig: str) -> set[str]:
        return {src for src, dst in self.edges if dst == callee_sig}

    def reachable_methods(self) -> set[str]:
        return {sig for edge in self.edges for sig in edge}

    def num_edges(self) -> int:
        return len(self.edges)


def _cha_targets(scene: Scene, stmt: Statement) -> list[str]:
    """Resolve a call statement to CHA target full signatures."""
    callee = stmt.callee
    if callee is None:
        return []
    targets: list[str] = []

    def add_target(class_name: str):
        resolved = scene.resolve_method(class_name, callee.method_name, callee.param_types)
        if resolved is not None:
            sig = resolved[1].signature.full_signature()
            if sig not in targets:
                targets.append(sig)

    is_virtual = stmt.receiver is not None and not _is_static_callee(scene, callee)
    if is_virtual:
        # CHA: declared class plus every subclass override.
        candidate_classes = [callee.class_name] + sorted(scene.all_subclasses(callee.class_name))
        for class_name in candidate_classes:
            add_target(class_name)
    else:
        add_target(callee.class_name)

    if not targets:
        # External / library method without a body in the scene.
        targets.append(callee.full_signature())
    return targets


def _is_static_callee(scene: Scene, callee: MethodSignature) -> bool:
    resolved = scene.resolve_method(callee.class_name, callee.method_name, callee.param_types)
    if resolved is None:
        return False
    return resolved[1].is_static


def build_cha_call_graph(
    scene: Scene, entry_points: list[MethodSignature] | None = None
) -> CallGraph:
    """Build a CHA call graph by breadth-first traversal from entry points."""
    graph = CallGraph()
    worklist: deque[str] = deque()
    visited: set[str] = set()

    if entry_points:
        seeds = []
        for sig in entry_points:
            resolved = scene.resolve_method(sig.class_name, sig.method_name, sig.param_types)
            if resolved is not None:
                seeds.append(resolved[1].signature.full_signature())
    else:
        seeds = [m.signature.full_signature() for _, m in scene.entry_methods()]

    for sig in seeds:
        if sig not in visited:
            visited.add(sig)
            worklist.append(sig)

    while worklist:
        caller_sig = worklist.popleft()
        entry = scene.get_method(caller_sig)
        if entry is None:
            graph.external_callees.add(caller_sig)
            continue
        _, method = entry
        if method.body is None:
            continue
        for stmt in method.body.statements:
            if stmt.kind != "call" or stmt.callee is None:
                continue
            for callee_sig in _cha_targets(scene, stmt):
                graph.add_edge(caller_sig, stmt.stmt_id, callee_sig)
                if callee_sig not in visited:
                    visited.add(callee_sig)
                    worklist.append(callee_sig)
    return graph


# ---------------------------------------------------------------------------
# Optimizations: copy propagation and dead-code elimination
# ---------------------------------------------------------------------------

_COPY_KINDS = {"assign"}


def _is_local(name: str | None) -> bool:
    if not name:
        return False
    if name.startswith(('"', "@")):
        return False
    if name in ("null", "true", "false"):
        return False
    try:
        float(name)
        return False
    except (TypeError, ValueError):
        return True


def copy_propagate(statements: list[Statement]) -> tuple[list[Statement], int]:
    """Propagate simple ``a = b`` copies into downstream uses.

    Returns the (possibly rewritten) statement list and the number of
    propagated uses. Copy statements themselves are kept; dead-code
    elimination removes them afterwards.
    """
    result: list[Statement] = []
    copies: dict[str, str] = {}
    propagated = 0

    def resolve(var: str | None) -> str | None:
        nonlocal propagated
        if var is None or var not in copies:
            return var
        seen = set()
        cur = var
        while cur in copies and cur not in seen:
            seen.add(cur)
            cur = copies[cur]
        if cur != var:
            propagated += 1
        return cur

    def invalidate(var: str | None):
        if var is None:
            return
        copies.pop(var, None)
        for lhs, rhs in list(copies.items()):
            if rhs == var:
                del copies[lhs]

    for stmt in statements:
        stmt = Statement(**{**stmt.__dict__})
        if stmt.kind in _COPY_KINDS and _is_local(stmt.rhs) and stmt.lhs:
            # New copy: lhs = rhs (invalidate old info first).
            invalidate(stmt.lhs)
            stmt.rhs = resolve(stmt.rhs)
            stmt.rhs_vars = [resolve(v) for v in stmt.rhs_vars]
            copies[stmt.lhs] = stmt.rhs
        else:
            if stmt.rhs is not None and _is_local(stmt.rhs):
                stmt.rhs = resolve(stmt.rhs)
            stmt.rhs_vars = [resolve(v) for v in stmt.rhs_vars]
            stmt.args = [resolve(a) for a in stmt.args]
            stmt.receiver = resolve(stmt.receiver)
            if stmt.field_ref is not None:
                new_base = resolve(stmt.field_ref.base)
                if new_base != stmt.field_ref.base:
                    from program_model import FieldRef

                    stmt.field_ref = FieldRef(
                        base=new_base,
                        field_name=stmt.field_ref.field_name,
                        field_type=stmt.field_ref.field_type,
                        declaring_class=stmt.field_ref.declaring_class,
                    )
            if stmt.lhs:
                invalidate(stmt.lhs)
        result.append(stmt)
    return result, propagated


_SIDE_EFFECT_KINDS = {"call", "field_store", "return", "if", "identity"}


def eliminate_dead_code(statements: list[Statement]) -> tuple[list[Statement], int]:
    """Remove dead ``assign``/``new``/``nop`` statements (no live uses).

    Iterates to a fixpoint. Statements with side effects are never removed.
    Returns the filtered list and the number of removed statements.
    """
    current = list(statements)
    removed_total = 0
    while True:
        used: set[str] = set()
        for stmt in current:
            if _is_local(stmt.rhs):
                used.add(stmt.rhs)
            used.update(v for v in stmt.rhs_vars if _is_local(v))
            used.update(a for a in stmt.args if _is_local(a))
            if _is_local(stmt.receiver):
                used.add(stmt.receiver)
            if stmt.field_ref is not None and _is_local(stmt.field_ref.base):
                used.add(stmt.field_ref.base)
        kept: list[Statement] = []
        removed = 0
        for stmt in current:
            if stmt.kind in ("nop",):
                removed += 1
                continue
            if (
                stmt.kind in ("assign", "new")
                and stmt.lhs
                and stmt.lhs not in used
                and not stmt.is_source
                and not stmt.is_sink
            ):
                removed += 1
                continue
            kept.append(stmt)
        removed_total += removed
        current = kept
        if removed == 0:
            break
    return current, removed_total


# ---------------------------------------------------------------------------
# Benchmark driver
# ---------------------------------------------------------------------------

def analyze_benchmark(path: str) -> dict:
    """Run the full layer-1 pipeline on one benchmark JSON file."""
    program = load_program(path)
    scene = Scene(program)
    graph = build_cha_call_graph(scene)

    stmts_before = 0
    stmts_after = 0
    copies = 0
    dead = 0
    method_count = 0
    for cls in program.classes:
        for method in cls.methods:
            if method.body is None:
                continue
            method_count += 1
            stmts_before += len(method.body.statements)
            propagated_stmts, n_copies = copy_propagate(method.body.statements)
            optimized, n_dead = eliminate_dead_code(propagated_stmts)
            stmts_after += len(optimized)
            copies += n_copies
            dead += n_dead

    return {
        "program": program,
        "scene": scene,
        "call_graph": graph,
        "classes": len(program.classes),
        "methods": method_count,
        "reachable": len(
            {sig for sig in graph.reachable_methods() if scene.get_method(sig) is not None}
        ),
        "edges": graph.num_edges(),
        "stmts_before": stmts_before,
        "stmts_after": stmts_after,
        "copies_propagated": copies,
        "dead_removed": dead,
    }


def main(argv: list[str]) -> int:
    bench_dir = argv[1] if len(argv) > 1 else os.path.join(os.path.dirname(__file__), "benchmarks")
    paths = sorted(
        os.path.join(bench_dir, f) for f in os.listdir(bench_dir) if f.endswith(".json")
    )
    for path in paths:
        with Timer() as timer:
            stats = analyze_benchmark(path)
        program = stats["program"]
        print("LAYER: soot")
        print(f"BENCHMARK: {program.name}")
        print(f"CLASSES: {stats['classes']}")
        print(f"METHODS: {stats['methods']}")
        print(f"REACHABLE_METHODS: {stats['reachable']}")
        print(f"CALLGRAPH_EDGES: {stats['edges']}")
        print(f"STMTS_BEFORE_OPT: {stats['stmts_before']}")
        print(f"STMTS_AFTER_OPT: {stats['stmts_after']}")
        print(f"COPIES_PROPAGATED: {stats['copies_propagated']}")
        print(f"DEAD_CODE_REMOVED: {stats['dead_removed']}")
        print(f"ANALYSIS_TIME_MS: {timer.elapsed_ms:.3f}")
        print("STATUS: OK")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

