"""
stubdroid_analysis.py — StubDroid-style library-summary layer.

Generates method summaries for library classes automatically:

- If a statement carries ``metadata["summary_flow"]`` (e.g.
  ``"parameter0 -> this._elements"``), the declared flow is used directly.
- Otherwise flows are derived by symbolic intraprocedural tag propagation:
  parameters are tagged ``parameterI``, ``this`` is tagged ``this``, and field
  loads from ``this`` produce ``this.<field>`` tags. Tags reaching a ``return``
  yield a ``-> return`` flow; tags stored into a ``this`` field yield a
  ``-> this.<field>`` flow.

The summaries are then fed to the FlowDroid-style IFDS taint analysis
(``flowdroid_analysis.IFDSTaintAnalysis``) so taint propagates through library
methods without analyzing their bodies.

Runs standalone: ``python3 stubdroid_analysis.py [benchmarks_dir]`` and prints
``KEY: VALUE`` experiment lines per benchmark.
"""

from __future__ import annotations

import os
import sys
from dataclasses import dataclass, field

from program_model import (
    ClassDef,
    Method,
    MethodBody,
    Program,
    Statement,
    load_program,
)
from soot_analysis import Scene, build_cha_call_graph

# The FlowDroid layer is developed concurrently; import it defensively so the
# summary generator remains usable/testable even if the module is not (yet)
# present. The summary-aware analysis raises a clear error when it is missing.
try:
    from flowdroid_analysis import (
        AccessPath,
        IFDSTaintAnalysis,
        Leak,
        TaintFact,
        analyze_program,
        match_leaks,
    )

    _FLOWDROID_AVAILABLE = True
except ImportError:  # pragma: no cover - only while flowdroid layer is absent
    AccessPath = None
    IFDSTaintAnalysis = None
    Leak = None
    TaintFact = None
    analyze_program = None
    match_leaks = None
    _FLOWDROID_AVAILABLE = False


# ---------------------------------------------------------------------------
# Summary data model
# ---------------------------------------------------------------------------


@dataclass
class SummaryFlow:
    """One data-flow edge of a method summary (StubDroid ``SourceSink``)."""

    source: str  # "parameterI" | "this" | "this.<field>"
    target: str  # "return" | "this" | "this.<field>"

    def __str__(self) -> str:
        return f"{self.source} -> {self.target}"


@dataclass
class MethodSummary:
    """All flows of one library method."""

    signature: str  # full signature
    class_name: str
    method_name: str
    flows: list[SummaryFlow] = field(default_factory=list)
    from_metadata: bool = False


# ---------------------------------------------------------------------------
# Summary generation
# ---------------------------------------------------------------------------


def _parse_metadata_flow(text: str) -> SummaryFlow | None:
    """Parse a ``"src -> dst"`` descriptor from statement metadata."""
    if not isinstance(text, str) or "->" not in text:
        return None
    src, dst = text.split("->", 1)
    src, dst = src.strip(), dst.strip()
    if not src or not dst:
        return None
    return SummaryFlow(source=src, target=dst)


def _metadata_flows(body: MethodBody) -> list[SummaryFlow]:
    flows: list[SummaryFlow] = []
    seen: set[tuple[str, str]] = set()
    for stmt in body.statements:
        flow = _parse_metadata_flow(stmt.metadata.get("summary_flow"))
        if flow is not None and (flow.source, flow.target) not in seen:
            seen.add((flow.source, flow.target))
            flows.append(flow)
    return flows


def _derive_flows(body: MethodBody) -> list[SummaryFlow]:
    """Derive flows by symbolic intraprocedural tag propagation.

    Tags: ``parameterI`` for parameter locals, ``this`` for the this-local,
    ``this.<field>`` for values loaded from a field of ``this``. Iterates the
    statement list to a fixpoint (bodies are small).
    """
    tags: dict[str, set[str]] = {}
    flows: set[tuple[str, str]] = set()
    this_local = body.this_local

    def add_tags(var: str | None, new_tags: set[str]) -> bool:
        if not var or not new_tags:
            return False
        slot = tags.setdefault(var, set())
        before = len(slot)
        slot |= new_tags
        return len(slot) != before

    def tags_of(var: str | None) -> set[str]:
        return tags.get(var, set()) if var else set()

    def is_this(var: str | None) -> bool:
        return bool(var) and (var == this_local or "this" in tags_of(var))

    def rhs_tags(stmt: Statement) -> set[str]:
        result = set(tags_of(stmt.rhs))
        for var in stmt.rhs_vars:
            result |= tags_of(var)
        return result

    changed = True
    while changed:
        changed = False
        for stmt in body.statements:
            if stmt.kind == "identity":
                # Seed tags: "@this" -> "this", "@parameterI" -> "parameterI".
                if stmt.rhs == "@this":
                    changed |= add_tags(stmt.lhs, {"this"})
                elif stmt.rhs and stmt.rhs.startswith("@parameter"):
                    index = stmt.rhs[len("@parameter"):]
                    if index.isdigit():
                        changed |= add_tags(stmt.lhs, {f"parameter{index}"})
            elif stmt.kind == "assign":
                changed |= add_tags(stmt.lhs, rhs_tags(stmt))
            elif stmt.kind == "field_load":
                if stmt.field_ref is not None and is_this(stmt.field_ref.base):
                    tag = f"this.{stmt.field_ref.field_name}"
                    changed |= add_tags(stmt.lhs, {tag})
            elif stmt.kind == "field_store":
                if stmt.field_ref is not None and is_this(stmt.field_ref.base):
                    target = f"this.{stmt.field_ref.field_name}"
                    for tag in rhs_tags(stmt):
                        if (tag, target) not in flows:
                            flows.add((tag, target))
                            changed = True
            elif stmt.kind == "return":
                for tag in rhs_tags(stmt):
                    if (tag, "return") not in flows:
                        flows.add((tag, "return"))
                        changed = True
            # "new", "call", "if", "nop": no summary-flow contribution.

    return [SummaryFlow(source=src, target=dst) for src, dst in sorted(flows)]


class SummaryGenerator:
    """Generates StubDroid-style summaries for all library methods."""

    def __init__(self, scene: Scene):
        self.scene = scene

    def _summarize_method(self, cls: ClassDef, method: Method) -> MethodSummary | None:
        body = method.body
        if body is None:
            return None
        flows = _metadata_flows(body)
        from_metadata = bool(flows)
        if not from_metadata:
            flows = _derive_flows(body)
        if not flows:
            return None
        return MethodSummary(
            signature=method.signature.full_signature(),
            class_name=cls.name,
            method_name=method.signature.method_name,
            flows=flows,
            from_metadata=from_metadata,
        )

    def generate(self) -> dict[str, MethodSummary]:
        """One summary per library-class method with a body and >= 1 flow."""
        summaries: dict[str, MethodSummary] = {}
        for cls in self.scene.program.classes:
            if not cls.is_library:
                continue
            for method in cls.methods:
                summary = self._summarize_method(cls, method)
                if summary is not None:
                    summaries[summary.signature] = summary
        return summaries


def summaries_to_dict(
    summaries: dict[str, MethodSummary]
) -> dict[str, list[tuple[str, str]]]:
    """Adapter from MethodSummary objects to the IFDSTaintAnalysis format."""
    return {
        sig: [(flow.source, flow.target) for flow in summary.flows]
        for sig, summary in summaries.items()
    }


# ---------------------------------------------------------------------------
# Summary-aware taint analysis
# ---------------------------------------------------------------------------


def _require_flowdroid():
    if not _FLOWDROID_AVAILABLE:
        raise RuntimeError(
            "flowdroid_analysis is not available; the summary-aware taint "
            "analysis requires the Layer 2 module (flowdroid_analysis.py)."
        )


class SummaryAwareTaintAnalysis:
    """Runs the IFDS taint analysis with generated library summaries."""

    def __init__(self, program: Program):
        _require_flowdroid()
        self.program = program
        self.scene = Scene(program)
        self.call_graph = build_cha_call_graph(self.scene)
        self.summaries: dict[str, MethodSummary] = SummaryGenerator(
            self.scene
        ).generate()
        self.analysis = IFDSTaintAnalysis(
            program,
            self.scene,
            self.call_graph,
            summaries=summaries_to_dict(self.summaries),
        )
        self.leaks: list = []

    def run(self) -> list:
        self.leaks = self.analysis.run()
        return self.leaks


def analyze_program_with_summaries(
    program: Program,
) -> tuple[list, dict[str, MethodSummary]]:
    """Convenience entry point: (detected leaks, generated summaries)."""
    analysis = SummaryAwareTaintAnalysis(program)
    leaks = analysis.run()
    return leaks, analysis.summaries


# ---------------------------------------------------------------------------
# Benchmark driver
# ---------------------------------------------------------------------------


def _leak_line(leak) -> str:
    path = " -> ".join(leak.tainted_path)
    return (
        f"LEAK: source={leak.source_method}:{leak.source_stmt} "
        f"sink={leak.sink_method}:{leak.sink_stmt} path={path}"
    )


def run_benchmark(path: str) -> bool:
    """Run the summary-aware pipeline on one benchmark; print KEY: VALUE lines.

    Returns True iff the benchmark PASSes (precision == recall == 1.0).
    """
    program = load_program(path)
    analysis = SummaryAwareTaintAnalysis(program)
    leaks = analysis.run()
    summaries = analysis.summaries

    print("LAYER: stubdroid")
    print(f"BENCHMARK: {program.name}")
    print(f"SUMMARIES_GENERATED: {len(summaries)}")
    for sig in sorted(summaries):
        summary = summaries[sig]
        flow_text = "; ".join(str(flow) for flow in summary.flows)
        print(f"SUMMARY: {sig} :: {flow_text}")

    expected = program.expected_leaks
    _, precision, recall = match_leaks(leaks, expected)
    status = "PASS" if precision == 1.0 and recall == 1.0 else "FAIL"

    print(f"EXPECTED_LEAKS: {len(expected)}")
    print(f"DETECTED_LEAKS: {len(leaks)}")
    ordered = sorted(
        leaks,
        key=lambda lk: (
            lk.source_method,
            lk.sink_method,
            lk.source_stmt,
            lk.sink_stmt,
        ),
    )
    for leak in ordered:
        print(_leak_line(leak))
    print(f"PRECISION: {precision:.2f}")
    print(f"RECALL: {recall:.2f}")
    print(f"STATUS: {status}")
    return status == "PASS"


def main(argv: list[str]) -> int:
    bench_dir = (
        argv[1]
        if len(argv) > 1
        else os.path.join(os.path.dirname(os.path.abspath(__file__)), "benchmarks")
    )
    paths = sorted(
        os.path.join(bench_dir, f) for f in os.listdir(bench_dir) if f.endswith(".json")
    )
    all_pass = True
    for path in paths:
        if not run_benchmark(path):
            all_pass = False
    print(f"OVERALL: {'PASS' if all_pass else 'FAIL'}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

