"""
flowdroid_analysis.py — FlowDroid-style IFDS taint analysis layer.

Implements a forward, flow-sensitive, interprocedural taint analysis over
the Jimple-like IR provided by the shared program model and the layer-1
``soot_analysis`` utilities (Scene registry, CFGs, CHA call graph):

- ``AccessPath`` / ``TaintFact`` / ``Leak``: the IFDS fact model.
- ``IFDSTaintAnalysis``: the fixpoint solver.
  - Per-method forward dataflow over the CFG (fixpoint per method).
  - Global, field-sensitive / object-insensitive field store keyed by
    ``(declaring_class, field_name)`` — gives cross-method lifecycle
    propagation and alias visibility.
  - Interprocedural arg->param / return->lhs mapping over the CHA call
    graph with a global fixpoint over reachable methods.
  - Default taint-through rule for bodyless library calls.
  - Optional method summaries applied at call sites instead of descending.
- ``analyze_program`` / ``match_leaks``: convenience driver + verification.

Runs standalone: ``python3 flowdroid_analysis.py [benchmarks_dir]`` and
prints ``KEY: VALUE`` experiment lines per benchmark.
"""

from __future__ import annotations

import glob
import os
import sys
from collections import deque
from dataclasses import dataclass

from program_model import (
    Method,
    MethodBody,
    Program,
    Statement,
    load_program,
)
from soot_analysis import (
    CFG,
    CallGraph,
    Scene,
    build_cfg,
    build_cha_call_graph,
)


# ---------------------------------------------------------------------------
# Fact model
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class AccessPath:
    """A tainted access path: a base local plus optional field suffixes."""

    base: str
    fields: tuple[str, ...] = ()

    def extend(self, field: str) -> "AccessPath":
        return AccessPath(self.base, self.fields + (field,))

    def __str__(self) -> str:
        if self.fields:
            return self.base + "." + ".".join(self.fields)
        return self.base


@dataclass
class TaintFact:
    """One taint fact: an access path tainted from a given source."""

    access_path: AccessPath
    source_stmt: int
    source_method: str
    category: str
    path: tuple[str, ...] = ()
    # Full signature of the method CONTAINING the source statement.
    source_method_sig: str = ""


@dataclass
class Leak:
    """A source-to-sink flow witnessed at a sink statement."""

    source_stmt: int
    sink_stmt: int
    source_method: str
    sink_method: str
    source_category: str
    sink_category: str
    tainted_path: list[str]
    source_method_sig: str
    sink_method_sig: str


def _fact_key(fact: TaintFact) -> tuple:
    """Deduplication key for the fixpoint (ignores the human-readable path)."""
    return (fact.source_stmt, fact.source_method, fact.source_method_sig, fact.category)


def _is_var(name: str | None) -> bool:
    """True for local variable names, False for constants/literals."""
    if not name:
        return False
    if name.startswith(('"', "@")):
        return False
    if name in ("null", "true", "false"):
        return False
    try:
        float(name)
        return False
    except (TypeError, ValueError):
        return True


# Fact maps are dicts: local name -> {fact_key: TaintFact}.
FactMap = dict


def _merge_facts(dst: FactMap, src: FactMap) -> bool:
    """Union ``src`` into ``dst``; returns True if ``dst`` changed."""
    changed = False
    for local, facts in src.items():
        slot = dst.setdefault(local, {})
        for key, fact in facts.items():
            if key not in slot:
                slot[key] = fact
                changed = True
    return changed


# ---------------------------------------------------------------------------
# The IFDS taint analysis
# ---------------------------------------------------------------------------

class IFDSTaintAnalysis:
    """Forward flow-sensitive interprocedural taint analysis (IFDS-style)."""

    def __init__(
        self,
        program: Program,
        scene: Scene | None = None,
        call_graph: CallGraph | None = None,
        summaries: dict[str, list[tuple[str, str]]] | None = None,
    ):
        self.program = program
        self.scene = scene if scene is not None else Scene(program)
        self.call_graph = (
            call_graph if call_graph is not None else build_cha_call_graph(self.scene)
        )
        self.summaries = summaries or {}

        self.leaks: list[Leak] = []
        self.facts_count: int = 0
        self.sources_count: int = 0
        self.sinks_count: int = 0
        # May-alias sets, kept for reporting (assign a = b on references).
        self.aliases: dict[str, set[str]] = {}

        # Global field store: (declaring_class, field_name) -> {key: TaintFact}.
        self._field_store: dict[tuple[str, str], dict] = {}
        # Interprocedural state.
        self._method_inputs: dict[str, FactMap] = {}
        self._method_returns: dict[str, dict] = {}
        self._cfgs: dict[str, CFG] = {}
        self._leak_map: dict[tuple, Leak] = {}
        self._source_stmts: set[tuple[str, int]] = set()
        self._sink_stmts: set[tuple[str, int]] = set()
        self._dirty = False
        # (caller sig, stmt id) -> CHA target signatures.
        self._site_targets: dict[tuple[str, int], list[str]] = {}
        for caller_sig, sites in self.call_graph.call_sites.items():
            for stmt_id, callee_sig in sites:
                self._site_targets.setdefault((caller_sig, stmt_id), []).append(callee_sig)

    # -- public driver ----------------------------------------------------

    def run(self) -> list[Leak]:
        """Iterate all reachable methods to a global fixpoint; return leaks."""
        methods = self._analyzable_methods()
        rounds = 0
        self._dirty = True
        while self._dirty and rounds < 1000:
            self._dirty = False
            rounds += 1
            for sig in methods:
                self._analyze_method(sig)
        self.leaks = [self._leak_map[key] for key in sorted(self._leak_map)]
        self.sources_count = len(self._source_stmts)
        self.sinks_count = len(self._sink_stmts)
        return self.leaks

    def _analyzable_methods(self) -> list[str]:
        sigs = set(self.call_graph.reachable_methods())
        for _, method in self.scene.entry_methods():
            sigs.add(method.signature.full_signature())
        result = []
        for sig in sigs:
            entry = self.scene.get_method(sig)
            if entry is not None and entry[1].body is not None:
                result.append(sig)
        return sorted(result)

    # -- per-method flow-sensitive analysis --------------------------------

    def _analyze_method(self, sig: str) -> None:
        cls, method = self.scene.get_method(sig)
        body = method.body
        cfg = self._cfgs.get(sig)
        if cfg is None:
            cfg = build_cfg(body)
            self._cfgs[sig] = cfg
        stmt_by_id = {s.stmt_id: s for s in cfg.statements}

        in_sets: dict[int, FactMap] = {s.stmt_id: {} for s in cfg.statements}
        entry_ids = cfg.entry_ids()
        if entry_ids:
            seeds = self._method_inputs.get(sig, {})
            in_sets[entry_ids[0]] = {loc: dict(facts) for loc, facts in seeds.items()}

        worklist = deque(entry_ids)
        queued = set(entry_ids)
        while worklist:
            sid = worklist.popleft()
            queued.discard(sid)
            stmt = stmt_by_id[sid]
            out = self._transfer(stmt, sig, in_sets[sid], body)
            for succ in cfg.successors.get(sid, []):
                if _merge_facts(in_sets[succ], out) and succ not in queued:
                    worklist.append(succ)
                    queued.add(succ)

    # -- transfer functions -------------------------------------------------

    def _transfer(self, stmt: Statement, sig: str, in_map: FactMap, body: MethodBody) -> FactMap:
        out: FactMap = {loc: dict(facts) for loc, facts in in_map.items()}
        kind = stmt.kind

        # Sources and sinks first: the default rule never applies to them.
        source_category = self._source_category(stmt)
        if source_category is not None:
            self._source_stmts.add((sig, stmt.stmt_id))
            if stmt.lhs:
                fact = TaintFact(
                    access_path=AccessPath(stmt.lhs),
                    source_stmt=stmt.stmt_id,
                    source_method=stmt.callee.method_name if stmt.callee else "<source>",
                    category=source_category,
                    path=(stmt.lhs,),
                    source_method_sig=sig,
                )
                self.facts_count += 1
                out[stmt.lhs] = {_fact_key(fact): fact}
            return out

        sink_category = self._sink_category(stmt)
        if sink_category is not None:
            self._sink_stmts.add((sig, stmt.stmt_id))
            self._check_sink(stmt, sig, out, sink_category)
            return out

        if kind in ("nop", "identity", "if"):
            return out

        if kind == "assign":
            facts = self._facts_of_vars(out, [stmt.rhs] + list(stmt.rhs_vars))
            if stmt.lhs:
                if facts:
                    out[stmt.lhs] = {
                        key: self._derive(fact, AccessPath(stmt.lhs), stmt.lhs)
                        for key, fact in facts.items()
                    }
                else:
                    # Untainted (e.g. constant) rhs kills the lhs.
                    out.pop(stmt.lhs, None)
                if _is_var(stmt.rhs) and self._is_reference(body, stmt.lhs, stmt.rhs):
                    self._record_alias(stmt.lhs, stmt.rhs)
            return out

        if kind == "new":
            if stmt.lhs:
                out.pop(stmt.lhs, None)
            return out

        if kind == "field_store":
            ref = stmt.field_ref
            if ref is not None:
                store_key = (ref.declaring_class, ref.field_name)
                facts = self._facts_of_vars(out, [stmt.rhs] + list(stmt.rhs_vars))
                if facts:
                    store = self._field_store.setdefault(store_key, {})
                    element = f"{ref.base}.{ref.field_name}"
                    for key, fact in facts.items():
                        if key not in store:
                            store[key] = self._derive(
                                fact, AccessPath(ref.base, (ref.field_name,)), element
                            )
                            self._dirty = True
            return out

        if kind == "field_load":
            ref = stmt.field_ref
            if ref is not None and stmt.lhs:
                stored = self._field_store.get((ref.declaring_class, ref.field_name), {})
                if stored:
                    loaded = {}
                    for key, fact in stored.items():
                        element = self._load_element(fact, ref.base, ref.field_name)
                        new_fact = self._derive(
                            fact, AccessPath(ref.base, (ref.field_name,)), element
                        )
                        loaded[key] = self._derive(
                            new_fact, AccessPath(stmt.lhs), stmt.lhs
                        )
                    out[stmt.lhs] = loaded
                else:
                    out.pop(stmt.lhs, None)
            return out

        if kind == "call":
            return self._transfer_call(stmt, sig, out)

        if kind == "return":
            facts = self._facts_of_vars(out, [stmt.rhs] + list(stmt.rhs_vars))
            if facts:
                returns = self._method_returns.setdefault(sig, {})
                for key, fact in facts.items():
                    if key not in returns:
                        returns[key] = fact
                        self._dirty = True
            return out

        return out

    def _transfer_call(self, stmt: Statement, sig: str, out: FactMap) -> FactMap:
        targets = self._site_targets.get((sig, stmt.stmt_id), [])
        lhs_facts: dict = {}
        any_external = False
        for target in targets:
            flows = self.summaries.get(target)
            if flows is not None:
                # Summary: apply flows at the call site; do NOT descend.
                self._apply_summary(stmt, flows, out, lhs_facts)
                continue
            entry = self.scene.get_method(target)
            if entry is not None and entry[1].body is not None:
                self._seed_callee(stmt, target, entry[1], out)
                if stmt.lhs:
                    for key, fact in self._method_returns.get(target, {}).items():
                        if key not in lhs_facts:
                            lhs_facts[key] = self._derive(
                                fact, AccessPath(stmt.lhs), stmt.lhs
                            )
            else:
                any_external = True

        if any_external or not targets:
            # Default taint-through rule for bodyless library calls:
            # any tainted arg/receiver taints the receiver and the lhs.
            tainted = self._facts_of_vars(
                out, list(stmt.args) + ([stmt.receiver] if stmt.receiver else [])
            )
            if tainted:
                if stmt.receiver and _is_var(stmt.receiver):
                    slot = out.setdefault(stmt.receiver, {})
                    for key, fact in tainted.items():
                        if key not in slot:
                            slot[key] = self._derive(
                                fact, AccessPath(stmt.receiver), stmt.receiver
                            )
                if stmt.lhs:
                    for key, fact in tainted.items():
                        if key not in lhs_facts:
                            lhs_facts[key] = self._derive(
                                fact, AccessPath(stmt.lhs), stmt.lhs
                            )

        if stmt.lhs and (targets or lhs_facts):
            if lhs_facts:
                out[stmt.lhs] = lhs_facts
            else:
                out.pop(stmt.lhs, None)
        return out

    # -- interprocedural helpers --------------------------------------------

    def _seed_callee(self, stmt: Statement, target: str, callee: Method, out: FactMap) -> None:
        """Map tainted receiver/args to the callee's this/param locals."""
        body = callee.body
        inputs = self._method_inputs.setdefault(target, {})
        callee_name = callee.signature.method_name

        if stmt.receiver and _is_var(stmt.receiver) and body.this_local:
            dest = inputs.setdefault(body.this_local, {})
            for key, fact in out.get(stmt.receiver, {}).items():
                if key not in dest:
                    dest[key] = self._derive(
                        fact,
                        AccessPath(body.this_local),
                        f"{body.this_local}({callee_name})",
                    )
                    self._dirty = True

        for i, arg in enumerate(stmt.args):
            if i >= len(body.param_locals) or not _is_var(arg):
                continue
            arg_facts = out.get(arg, {})
            if not arg_facts:
                continue
            param = body.param_locals[i]
            dest = inputs.setdefault(param, {})
            for key, fact in arg_facts.items():
                if key not in dest:
                    dest[key] = self._derive(
                        fact, AccessPath(param), f"{param}({callee_name})"
                    )
                    self._dirty = True

    # -- summaries ------------------------------------------------------------

    def _apply_summary(
        self, stmt: Statement, flows: list[tuple[str, str]], out: FactMap, lhs_facts: dict
    ) -> None:
        callee_class = stmt.callee.class_name if stmt.callee else ""
        for src, dst in flows:
            for key, fact in self._summary_source_facts(src, stmt, out, callee_class).items():
                self._summary_apply_dst(dst, key, fact, stmt, out, lhs_facts, callee_class)

    def _summary_source_facts(
        self, src: str, stmt: Statement, out: FactMap, callee_class: str
    ) -> dict:
        if src == "this":
            return dict(out.get(stmt.receiver, {})) if stmt.receiver else {}
        if src.startswith("this."):
            return dict(self._field_store.get((callee_class, src[len("this."):]), {}))
        if src.startswith("parameter"):
            idx = int(src[len("parameter"):])
            if idx < len(stmt.args) and _is_var(stmt.args[idx]):
                return dict(out.get(stmt.args[idx], {}))
        return {}

    def _summary_apply_dst(
        self,
        dst: str,
        key: tuple,
        fact: TaintFact,
        stmt: Statement,
        out: FactMap,
        lhs_facts: dict,
        callee_class: str,
    ) -> None:
        if dst == "return":
            if stmt.lhs and key not in lhs_facts:
                lhs_facts[key] = self._derive(fact, AccessPath(stmt.lhs), stmt.lhs)
        elif dst == "this":
            if stmt.receiver and _is_var(stmt.receiver):
                slot = out.setdefault(stmt.receiver, {})
                if key not in slot:
                    slot[key] = self._derive(fact, AccessPath(stmt.receiver), stmt.receiver)
        elif dst.startswith("this."):
            field_name = dst[len("this."):]
            store = self._field_store.setdefault((callee_class, field_name), {})
            if key not in store:
                base = stmt.receiver or "this"
                store[key] = self._derive(
                    fact, AccessPath(base, (field_name,)), f"{base}.{field_name}"
                )
                self._dirty = True
        elif dst.startswith("parameter"):
            idx = int(dst[len("parameter"):])
            if idx < len(stmt.args) and _is_var(stmt.args[idx]):
                slot = out.setdefault(stmt.args[idx], {})
                if key not in slot:
                    slot[key] = self._derive(
                        fact, AccessPath(stmt.args[idx]), stmt.args[idx]
                    )

    # -- sources, sinks, leaks -------------------------------------------------

    def _source_category(self, stmt: Statement) -> str | None:
        if stmt.is_source:
            return stmt.source_category or "SOURCE"
        if stmt.kind == "call" and stmt.callee is not None:
            for entry in self.program.source_sink_spec.get("sources", []):
                if (
                    entry.get("class_name") == stmt.callee.class_name
                    and entry.get("method_name") == stmt.callee.method_name
                ):
                    return entry.get("category") or "SOURCE"
        return None

    def _sink_category(self, stmt: Statement) -> str | None:
        if stmt.is_sink:
            return stmt.sink_category or "SINK"
        if stmt.kind == "call" and stmt.callee is not None:
            for entry in self.program.source_sink_spec.get("sinks", []):
                if (
                    entry.get("class_name") == stmt.callee.class_name
                    and entry.get("method_name") == stmt.callee.method_name
                ):
                    return entry.get("category") or "SINK"
        return None

    def _check_sink(self, stmt: Statement, sig: str, out: FactMap, sink_category: str) -> None:
        """Record a Leak for every tainted fact reaching an arg or receiver."""
        candidates = list(stmt.args) + ([stmt.receiver] if stmt.receiver else [])
        sink_method = stmt.callee.method_name if stmt.callee else "<sink>"
        seen: set[tuple] = set()
        for var in candidates:
            if not _is_var(var):
                continue
            for key in sorted(out.get(var, {}), key=str):
                if key in seen:
                    continue
                seen.add(key)
                fact = out[var][key]
                leak_key = (
                    fact.source_stmt,
                    fact.source_method,
                    fact.source_method_sig,
                    stmt.stmt_id,
                    sink_method,
                    sig,
                )
                if leak_key in self._leak_map:
                    continue
                self._leak_map[leak_key] = Leak(
                    source_stmt=fact.source_stmt,
                    sink_stmt=stmt.stmt_id,
                    source_method=fact.source_method,
                    sink_method=sink_method,
                    source_category=fact.category,
                    sink_category=sink_category,
                    tainted_path=list(fact.path),
                    source_method_sig=fact.source_method_sig,
                    sink_method_sig=sig,
                )

    # -- small utilities ---------------------------------------------------------

    def _facts_of_vars(self, facts: FactMap, names) -> dict:
        """Union of facts held by the given variables (constants skipped)."""
        result: dict = {}
        for name in names:
            if not _is_var(name):
                continue
            for key, fact in facts.get(name, {}).items():
                if key not in result:
                    result[key] = fact
        return result

    def _derive(self, fact: TaintFact, access_path: AccessPath, element: str | None) -> TaintFact:
        """New fact at a new location, extending the human-readable path."""
        path = fact.path
        if element and (not path or path[-1] != element):
            path = path + (element,)
        self.facts_count += 1
        return TaintFact(
            access_path=access_path,
            source_stmt=fact.source_stmt,
            source_method=fact.source_method,
            category=fact.category,
            path=path,
            source_method_sig=fact.source_method_sig,
        )

    def _load_element(self, fact: TaintFact, base: str, field_name: str) -> str | None:
        """Path element for a field load, annotating loads through aliases."""
        element = f"{base}.{field_name}"
        if fact.path:
            last = fact.path[-1]
            if last == element:
                return None
            suffix = "." + field_name
            if last.endswith(suffix):
                stored_base = last[: -len(suffix)]
                if stored_base != base and stored_base in self.aliases.get(base, set()):
                    return f"{base}.{field_name}(alias)"
        return element

    def _is_reference(self, body: MethodBody, *names: str) -> bool:
        types = {v.name: v.var_type for v in body.locals}
        for name in names:
            var_type = types.get(name)
            if var_type is not None and var_type.is_primitive:
                return False
        return True

    def _record_alias(self, lhs: str, rhs: str) -> None:
        """``assign a = b`` on references: ``a`` may-alias ``b`` (reporting)."""
        slot = self.aliases.setdefault(lhs, set())
        slot.add(rhs)
        slot |= self.aliases.get(rhs, set())


# ---------------------------------------------------------------------------
# Convenience driver + verification
# ---------------------------------------------------------------------------

def analyze_program(program: Program, summaries=None) -> list[Leak]:
    """Build the scene/call graph and run the taint analysis."""
    return IFDSTaintAnalysis(program, summaries=summaries).run()


def match_leaks(detected: list[Leak], expected: list[dict]) -> tuple[int, float, float]:
    """Match detected against expected leaks by (source_method, sink_method).

    Returns (num_matched_expected, precision, recall).
    """

    def matches(leak: Leak, exp: dict) -> bool:
        return (
            leak.source_method == exp.get("source_method")
            and leak.sink_method == exp.get("sink_method")
        )

    matched_expected = sum(
        1 for exp in expected if any(matches(leak, exp) for leak in detected)
    )
    matched_detected = sum(
        1 for leak in detected if any(matches(leak, exp) for exp in expected)
    )
    precision = matched_detected / len(detected) if detected else 1.0
    recall = matched_expected / len(expected) if expected else 1.0
    return matched_expected, precision, recall


# ---------------------------------------------------------------------------
# Standalone benchmark driver
# ---------------------------------------------------------------------------

def main(argv: list[str]) -> int:
    bench_dir = (
        argv[1]
        if len(argv) > 1
        else os.path.join(os.path.dirname(os.path.abspath(__file__)), "benchmarks")
    )
    paths = sorted(glob.glob(os.path.join(bench_dir, "*.json")))
    overall = True
    for path in paths:
        program = load_program(path)
        analysis = IFDSTaintAnalysis(program)
        leaks = analysis.run()
        _matched, precision, recall = match_leaks(leaks, program.expected_leaks)
        status = "PASS" if precision == 1.0 and recall == 1.0 else "FAIL"
        if status == "FAIL":
            overall = False
        print("LAYER: flowdroid")
        print(f"BENCHMARK: {program.name}")
        print(f"SOURCES: {analysis.sources_count}")
        print(f"SINKS: {analysis.sinks_count}")
        print(f"TAINT_FACTS: {analysis.facts_count}")
        print(f"EXPECTED_LEAKS: {len(program.expected_leaks)}")
        print(f"DETECTED_LEAKS: {len(leaks)}")
        for leak in leaks:
            print(
                f"LEAK: source={leak.source_method}:{leak.source_stmt} "
                f"sink={leak.sink_method}:{leak.sink_stmt} "
                f"path={' -> '.join(leak.tainted_path)}"
            )
        print(f"PRECISION: {precision}")
        print(f"RECALL: {recall}")
        print(f"STATUS: {status}")
    print(f"OVERALL: {'PASS' if overall else 'FAIL'}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

